CHANGELOG = "## [0.251.0] - a reopened level shows where it stands\n\n**Save and reopen** (the factory's roadmap 318; `docs/AUTHORING_LOOP.md`).\n\n### Added\n- **`packages/service/standing.py`**, returned by `open_design` as `standing`. It reads the records each step left\n  beside the design (the worker already reads them for its next step):\n  - the newest layouts, as `generate_layouts` answered, with the controls that rebuild the layout and changed since;\n  - the chosen layout, from the workspace's approvals;\n  - the last walk and the last export, each with `current` true only when it is of the design's revision now, and\n    the export saying whether its snapshot folder is still there.\n  - A missing record is `None`; one that cannot be read is listed in `problems`, not skipped.\n- The build record keeps the recommendation and the plans' key, so reopened layouts read as they did when generated.\n- **The Level tab** fills from the standing on every open: the layouts with the chosen one selected and its plan, the\n  last walk and the last export with its checklist, each saying when the level has changed since.\n\n### Fixed\n- Opening a level after another left the other's layouts, walk and export on the Level tab. Every open now clears\n  them first.\n\n### Measured\n- Opened with this release: the factory's two trial levels read back with their three layouts, the chosen seed 9205,\n  and a current walk and export each. The second's snapshot folder had been deleted, which the standing reports.\n\n### Tests\n- `tests/service/test_standing.py` (fails on 0.250.0):\n  - a new level stands nowhere;\n  - after a walk and export both are current, the chosen layout is read, and a deleted snapshot is reported;\n  - a lighting change makes the walk old and keeps the layouts; a layout change makes them stale;\n  - the newest revision's record wins, and an unreadable record is reported.\n- `apps/godot/tests/test_level_reopen.gd`: the chosen layout selected over the recommended one, old walk and export\n  saying so, and a level opened after another showing none of it.\n\n"
OLD_VERSION, NEW_VERSION = '0.250.0', '0.251.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
